import type { Invoice, RouteDecision } from '@paperflow/extraction';
import manifest from '../samples.json';

/** One-click demo documents, generated by `pnpm --filter @paperflow/eval generate` into public/samples */
export interface Sample {
  id: string;
  title: string;
  kind: string;
  file: string;
  preview: string;
  mimeType: string;
  sha256: string;
  expectedRoute: RouteDecision['route'];
  invoice: Invoice;
}

export const SAMPLES = manifest as Sample[];

export const sampleById = (id: string) => SAMPLES.find((s) => s.id === id);
export const sampleBySha = (sha: string) => SAMPLES.find((s) => s.sha256 === sha);
